=== footer/index.tsx 1-215 ===
      1	import React, { useEffect, useState } from 'react';
      2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
      3	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
      4	import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
      5	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
      6	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
      7	import { useHistory } from 'react-router-dom';
      8	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
      9	import { useContentfulClient } from 'app/hooks/useContentfulClient';
     10	import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
     11	import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
     12	import { FooterNavColumn } from './footerNavColumn';
     13	import { BottomBar } from './bottomBar';
     14	
     15	const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
     16	
     17	// ---------------------------------------------------------------------------
     18	// Types
     19	// ---------------------------------------------------------------------------
     20	type FooterProps = {
     21	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from index.stories.content.ts in stories/tests. */
     22	  data: FooterConfigEntry;
     23	  copyrightYear?: number;
     24	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
     25	  initialSubscribed?: boolean;
     26	  /**
     27	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
     28	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
     29	   */
     30	  enableNameCapture?: boolean;
     31	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
     32	   *  noop so the presentational Footer never navigates on its own. */
     33	  onLogoClick?: () => void;
     34	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
     35	  privacyPolicyHref?: string;
     36	};
     37	
     38	// ---------------------------------------------------------------------------
     39	// Footer
     40	// ---------------------------------------------------------------------------
     41	
     42	/**
     43	 * Zimmermann global footer — presentational. Receives its content as props and fetches
     44	 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
     45	 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
     46	 *
     47	 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
     48	 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
     49	 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
     50	 * only the footer's own shell layout: content row, nav-column wrapper, logo band, bottom bar.
     51	 *
     52	 * `data` is required by design: static content belongs in the story or in the container below,
     53	 * never baked into the component that renders production UI. Omneo email submit and Cookie
     54	 * Settings are separate stories (HPC-035, HPC-038).
     55	 */
     56	export const Footer = ({
     57	  data,
     58	  copyrightYear = new Date().getFullYear(),
     59	  initialSubscribed = false,
     60	  privacyPolicyHref = '#',
     61	  onLogoClick = noop,
     62	  enableNameCapture = false,
     63	}: FooterProps) => {
     64	  const {
     65	    subscribeHeading,
     66	    subscribeBody,
     67	    navGroups,
     68	    legalLinks = [],
     69	    copyrightOwner,
     70	    phoneHref,
     71	    whatsAppHref,
     72	    emailHref,
     73	  } = data.fields;
     74	
     75	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
     76	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
     77	
     78	  return (
     79	    <chakra.footer role="contentinfo" __css={styles.container}>
     80	      <chakra.div __css={styles.main}>
     81	        <chakra.div __css={styles.contentRow}>
     82	          <chakra.div __css={styles.subscribe}>
     83	            <ZimmSubscribeSection
     84	              heading={subscribeHeading ?? ''}
     85	              body={subscribeBody ?? ''}
     86	              initialSubscribed={initialSubscribed}
     87	              privacyPolicyHref={privacyPolicyHref}
     88	              enableNameCapture={enableNameCapture}
     89	            />
     90	          </chakra.div>
     91	
     92	          <chakra.div __css={styles.links}>
     93	            <chakra.div __css={styles.linksInner}>
     94	              {navGroups.map((group) => (
     95	                <FooterNavColumn
     96	                  key={group.sys.id}
     97	                  group={group}
     98	                  phoneHref={phoneHref}
     99	                  whatsAppHref={whatsAppHref}
    100	                  emailHref={emailHref}
    101	                />
    102	              ))}
    103	            </chakra.div>
    104	          </chakra.div>
    105	        </chakra.div>
    106	
    107	        <chakra.div __css={styles.logo}>
    108	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
    109	              The handler comes from FooterContainer — see the note there on why it uses
    110	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
    111	              reset only, so the logo keeps its own geometry. */}
    112	          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
    113	            <ZimmLogo variant="inverse" />
    114	          </chakra.button>
    115	        </chakra.div>
    116	      </chakra.div>
    117	
    118	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
    119	    </chakra.footer>
    120	  );
    121	};
    122	
    123	// ---------------------------------------------------------------------------
    124	// Container — the default export
    125	// ---------------------------------------------------------------------------
    126	
    127	/**
    128	 * Contentful's `include`-resolved response nests navGroups/links/regions but applies no
    129	 * region scoping of its own — narrow each region-aware array down to the current
    130	 * storefront via the shared resolveByRegion utilities.
    131	 */
    132	export const scopeToRegion = (config: FooterConfigEntry, siteId: string): FooterConfigEntry => {
    133	  const navGroups: FooterNavGroupEntry[] = config.fields.navGroups.map(
    134	    (group): FooterNavGroupEntry => ({
    135	      ...group,
    136	      fields: { ...group.fields, links: filterByRegion<LinkEntry>(group.fields.links, siteId) },
    137	    }),
    138	  );
    139	  const legalLinks: LinkEntry[] | undefined = config.fields.legalLinks
    140	    ? filterByRegion<LinkEntry>(config.fields.legalLinks, siteId)
    141	    : undefined;
    142	
    143	  return { ...config, fields: { ...config.fields, navGroups, legalLinks } };
    144	};
    145	
    146	/**
    147	 * The component SFCC actually renders. Base `_app/index.jsx` resolves
    148	 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
    149	 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
    150	 * wrapper is that seam, and the only place the Contentful fetch lives.
    151	 *
    152	 * HPC-034: fetches `footerConfig` entries via the Delivery API, then picks the entry scoped
    153	 * to the current storefront's region (falls back to the global/unscoped entry once one
    154	 * exists). Renders nothing while loading, on fetch failure, or when no entry resolves for
    155	 * this region — no fallback to placeholder content once wired to live data, so a Contentful
    156	 * outage doesn't silently ship stale placeholder copy to real shoppers. Note this puts a
    157	 * fetch inside `components/`, which components.md reserves for containers; if that matters,
    158	 * this should move into an `_app` override instead (Tier 2 shared shell — coordinate first).
    159	 */
    160	const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
    161	  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
    162	  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
    163	  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
    164	  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
    165	  // the same way on every storefront.
