import {chromium} from 'playwright';
const url = 'file://' + process.env.CLAUDE_JOB_DIR + '/tmp/b5probe/modal.html';
const cases = [
  ['WCAG 1.4.10 reflow target', 320, 256],
  ['iPhone SE portrait', 375, 667],
  ['iPhone SE landscape', 667, 375],
  ['iPhone 14 landscape', 844, 390],
  ['iPad landscape', 1024, 768],
  ['desktop 1280x800', 1280, 800],
  ['desktop @200% zoom (1.4.4)', 640, 400],
];
const b = await chromium.launch();
for (const [name, w, h] of cases) {
  const p = await b.newPage({viewport: {width: w, height: h}});
  await p.goto(url);
  const r = await p.evaluate(() => {
    const panel = document.getElementById('panel');
    const box = panel.getBoundingClientRect();
    const cont = document.getElementById('actions').getBoundingClientRect();
    return {
      panelH: Math.round(box.height), panelW: Math.round(box.width),
      top: Math.round(box.top), bottom: Math.round(box.bottom),
      scrollH: panel.scrollHeight, clientH: panel.clientHeight,
      overflowCSS: getComputedStyle(panel).overflowY,
      continueTop: Math.round(cont.top), continueBottom: Math.round(cont.bottom),
      vh: window.innerHeight,
    };
  });
  const clippedTop = Math.max(0, -r.top);
  const clippedBottom = Math.max(0, r.bottom - r.vh);
  const continueVisible = r.continueTop >= 0 && r.continueBottom <= r.vh;
  console.log(
    `${name.padEnd(28)} vp=${String(w).padStart(4)}x${String(h).padStart(3)} ` +
    `panel=${String(r.panelW).padStart(3)}x${String(r.panelH).padStart(3)} ` +
    `top=${String(r.top).padStart(5)} bottom=${String(r.bottom).padStart(4)} ` +
    `clippedAbove=${String(clippedTop).padStart(3)} clippedBelow=${String(clippedBottom).padStart(3)} ` +
    `overflowY=${r.overflowCSS} Continue-btn-fully-visible=${continueVisible}`
  );
  await p.close();
}
await b.close();
