import {chromium} from 'playwright';
const url = 'file://' + process.env.CLAUDE_JOB_DIR + '/tmp/b5probe/modal.html';
const variants = {
  'none (current)':            '',
  'CR: maxH calc(100dvh-40px) + overflowY auto': '#panel{max-height:calc(100dvh - 20px - 20px);overflow-y:auto}',
  'alt: maxH 100% + overflowY auto':             '#panel{max-height:100%;overflow-y:auto}',
};
const cases = [['320x256 (1.4.10)',320,256],['667x375 (SE landscape)',667,375],['640x400 (200% zoom)',640,400],['375x667 (SE portrait)',375,667]];
const b = await chromium.launch();
for (const [vname, css] of Object.entries(variants)) {
  console.log('\n### ' + vname);
  for (const [cname, w, h] of cases) {
    const p = await b.newPage({viewport:{width:w,height:h}});
    await p.goto(url);
    if (css) await p.addStyleTag({content: css});
    const r = await p.evaluate(() => {
      const panel = document.getElementById('panel');
      const box = panel.getBoundingClientRect();
      // can every focusable be scrolled into view inside the panel?
      const last = document.querySelector('#actions button[type=submit]');
      last.scrollIntoView({block:'nearest'});
      const lb = last.getBoundingClientRect();
      const first = document.querySelector('h2');
      first.scrollIntoView({block:'nearest'});
      const fb = first.getBoundingClientRect();
      return {h:Math.round(box.height), top:Math.round(box.top), bottom:Math.round(box.bottom),
        scrollable: panel.scrollHeight > panel.clientHeight,
        lastReachable: lb.top >= -1 && lb.bottom <= window.innerHeight+1,
        firstReachable: fb.top >= -1 && fb.bottom <= window.innerHeight+1,
        vh: window.innerHeight};
    });
    const above = Math.max(0,-r.top), below = Math.max(0, r.bottom - r.vh);
    console.log(`  ${cname.padEnd(24)} panelH=${String(r.h).padStart(3)} clippedAbove=${String(above).padStart(3)} clippedBelow=${String(below).padStart(3)} internalScroll=${String(r.scrollable).padEnd(5)} title-reachable=${String(r.firstReachable).padEnd(5)} Continue-reachable=${r.lastReachable}`);
    await p.close();
  }
}
await b.close();
